style.css:
@-moz-document domain("google.com") {
/* --- Maxident Theme Variables --- */
    :root {
        --maxident-pink: #ff4a8d;
        --maxident-dark-pink: #d62263;
        --maxident-black: #121212;
        --maxident-white: #ffffff;
        --text-primary: #ffffff;
        --text-secondary: #f0f0f0;
        --link-color: #ff8ebb;
        --link-visited: #d62263;
    }

    /* --- Gradient Background & Album Lettering --- */
    body {
        background: 
            /* MAXIDENT Lettering Watermark */
            linear-gradient(rgba(18, 18, 18, 0.65), rgba(18, 18, 18, 0.65)),
            url("data:image/svg+xml;utf8,<svg xmlns='http://w3.org' width='500' height='500' viewBox='0 0 500 500'><text x='50%' y='50%' font-family='Arial Black, Impact, sans-serif' font-size='60' font-weight='900' fill='rgba(255, 74, 141, 0.15)' text-anchor='middle' transform='rotate(-25 250 250)'>MAXIDENT</text></svg>"),
            /* Maxident Theme Gradient */
            linear-gradient(135deg, var(--maxident-black) 0%, var(--maxident-dark-pink) 50%, var(--maxident-pink) 100%) !important;
        background-attachment: fixed !important;
        background-size: auto, cubic-bezier(0,0,1,1), cover !important;
        color: var(--text-primary) !important;
    }

    /* --- Readability Adjustments for Google Interface --- */
    
    /* Search Results Wrapper */
    #center_col, #rcnt, .g, .kp-blk, .r2bis, .g-blk {
        background-color: rgba(18, 18, 18, 0.8) !important;
        border-radius: 12px !important;
        padding: 16px !important;
        margin-bottom: 12px !important;
        backdrop-filter: blur(5px);
        border: 1px solid rgba(255, 74, 141, 0.2) !important;
    }

    /* Text & Headings */
    h1, h2, h3, h3 span, span, em, p, .st {
        color: var(--text-primary) !important;
    }

    /* Dimmer description text for contrast hierarchy */
    .VwiC3b, .MUxGbd, .YyV6Be {
        color: var(--text-secondary) !important;
    }

    /* Links */
    a, a h3, .yuRUbf h3 {
        color: var(--link-color) !important;
    }

    a:visited, a:visited h3 {
        color: var(--link-visited) !important;
    }

    /* Search Bar Customization */
    .RNNXgb, .SDkEP {
        background: rgba(255, 255, 255, 0.9) !important;
        border: 2px solid var(--maxident-pink) !important;
    }

    .RNNXgb input {
        color: #000000 !important;
    }

    /* Tools and Header Navigation */
    .hdtb-mitem a, .KTSS4b, .GOE20b {
        color: var(--text-primary) !important;
    }

    /* Remove harsh white backgrounds from Google blocks */
    .sfbg, .MainHTML, .appbar {
        background: transparent !important;
    }
}
